  try {
    const userId = req.get('x-user-id');
    await billingClient.cancel(req.params.invoiceId, { userId });
    res.sendStatus(204);
  } catch (err) {
    next(err);
  }
});

// Billing service handler
async function cancelInvoice(invoiceId, context) {
  if (!context.userId) {
    throw new Error('Missing user identity');
  }

  const invoice = await invoices.findById(invoiceId);
  if (invoice.status !== 'open') {
    throw new Error('Invoice is not open');
  }

  await invoices.markCancelled(invoiceId);
}

